//#region src/lib/texte-riche.ts
/**
	* Texte riche des documents (GP V1) — format INTERNE, structuré et sûr.
	*
	* Un texte de devis (désignation, description, titre, commentaire, conditions, notes) reste une chaîne
	* `text` en base ; la mise en forme est portée par des balises à liste blanche, jamais par du HTML :
	*
	*   [b]gras[/b]   [i]italique[/i]   [u]souligné[/u]   [h]surligné[/h]   [c=rouge]couleur[/c]
	*
	* Tout ce qui n'est pas exactement une balise connue (nom, couleur de la palette, fermeture appariée) est
	* rendu comme du texte ordinaire : une saisie hostile ne peut produire ni balise HTML, ni script, ni style
	* arbitraire. Le rendu (`TexteRiche`) n'émet que des `<span>` React avec des styles issus de ce module :
	* aucune injection possible, aucune bibliothèque tierce, même texte à l'écran, en A4, en PDF et par e-mail.
	*/
	const COULEURS_TEXTE = [
		{
			cle: "accent",
			libelle: "Couleur accent (entreprise)",
			css: "var(--doc-accent, #c9a24a)"
		},
		{
			cle: "principale",
			libelle: "Couleur principale (entreprise)",
			css: "var(--doc-couleur, #0d1b2a)"
		},
		{
			cle: "rouge",
			libelle: "Rouge",
			css: "#b91c1c"
		},
		{
			cle: "vert",
			libelle: "Vert",
			css: "#15803d"
		},
		{
			cle: "bleu",
			libelle: "Bleu",
			css: "#1d4ed8"
		},
		{
			cle: "orange",
			libelle: "Orange",
			css: "#c2410c"
		},
		{
			cle: "gris",
			libelle: "Gris",
			css: "#6b7280"
		}
	];
	const BALISES = /* @__PURE__ */ new Set([
		"b",
		"i",
		"u",
		"h",
		"c"
	]);
	const COULEURS = new Set(COULEURS_TEXTE.map((c) => c.cle));
	/** Balise reconnue à la position `i` (ouvrante ou fermante), sinon `null`. */
	function lireBalise(texte, i) {
		if (texte[i] !== "[") return null;
		const fin = texte.indexOf("]", i);
		if (fin < 0 || fin - i > 16) return null;
		const corps = texte.slice(i + 1, fin);
		const m = /^(\/?)([a-z])(?:=([a-z]+))?$/.exec(corps);
		if (!m || !BALISES.has(m[2])) return null;
		const fermante = m[1] === "/";
		const balise = m[2];
		if (balise === "c") {
			if (fermante) {
				if (m[3]) return null;
				return {
					longueur: fin - i + 1,
					balise,
					fermante
				};
			}
			if (!m[3] || !COULEURS.has(m[3])) return null;
			return {
				longueur: fin - i + 1,
				balise,
				fermante,
				couleur: m[3]
			};
		}
		if (m[3]) return null;
		return {
			longueur: fin - i + 1,
			balise,
			fermante
		};
	}
	/**
	* Découpe un texte en segments stylés. Une balise mal fermée ou orpheline est restituée telle quelle
	* (texte littéral) : le résultat est toujours défini et ne perd jamais de caractères.
	*/
	function analyserTexteRiche(texte) {
		if (!texte) return [];
		const segments = [];
		const pile = [];
		let courant = "";
		const styleCourant = () => {
			const s = {};
			for (const b of pile) if (b.balise === "b") s.gras = true;
			else if (b.balise === "i") s.italique = true;
			else if (b.balise === "u") s.souligne = true;
			else if (b.balise === "h") s.surligne = true;
			else if (b.balise === "c" && b.couleur) s.couleur = b.couleur;
			return s;
		};
		const vider = () => {
			if (courant) {
				segments.push({
					...styleCourant(),
					texte: courant
				});
				courant = "";
			}
		};
		let i = 0;
		while (i < texte.length) {
			const b = lireBalise(texte, i);
			if (!b) {
				courant += texte[i];
				i += 1;
				continue;
			}
			if (!b.fermante) {
				vider();
				pile.push({
					balise: b.balise,
					couleur: b.couleur,
					position: segments.length,
					longueur: b.longueur
				});
				i += b.longueur;
				continue;
			}
			const ouverte = pile.length ? pile[pile.length - 1] : null;
			if (ouverte && ouverte.balise === b.balise) {
				vider();
				pile.pop();
				i += b.longueur;
				continue;
			}
			courant += texte.slice(i, i + b.longueur);
			i += b.longueur;
		}
		vider();
		if (pile.length) return reconstruireSansOuvertes(texte, pile.map((p) => p).map((p) => p.balise));
		return segments;
	}
	/** Repli sûr quand une balise ouvrante n'est jamais fermée : on retire les styles orphelins et on relance. */
	function reconstruireSansOuvertes(texte, orphelines) {
		let t = texte;
		for (const b of orphelines) {
			const motif = b === "c" ? /\[c=[a-z]+\](?![\s\S]*\[c=[a-z]+\])/ : new RegExp(`\\[${b}\\](?![\\s\\S]*\\[${b}\\])`);
			t = t.replace(motif, (m) => `␀${m.slice(1)}`);
		}
		return analyserTexteRiche(t.replace(/␀/g, "")).map((s) => ({
			...s,
			texte: s.texte.replace(//g, "[")
		}));
	}
	/** Texte sans balises (recherche, pagination, exports texte). */
	function texteBrut(texte) {
		return analyserTexteRiche(texte).map((s) => s.texte).join("");
	}
	/** Style CSS (inline, sans HTML) d'un segment. */
	function styleSegment(s) {
		const style = {};
		if (s.gras) style.fontWeight = "700";
		if (s.italique) style.fontStyle = "italic";
		if (s.souligne) style.textDecoration = "underline";
		if (s.surligne) style.backgroundColor = "#fde68a";
		if (s.couleur) style.color = COULEURS_TEXTE.find((c) => c.cle === s.couleur)?.css ?? "inherit";
		return style;
	}
