	function elementsFictifs(o = {}) {
		const elements = [];
		for (let i = 0; i < (o.lignesLibres ?? 2); i += 1) elements.push({
			type: "ligne",
			ordre: i + 1,
			ligne: {
				cle: `l${i + 1}`,
				designation: `Prestation fictive n° ${i + 1}`,
				description: i % 3 === 0 ? "Description fictive destinée au client, sur une ou deux lignes selon la largeur." : null,
				type: "forfait",
				quantite: 1 + i % 4,
				unite: "u",
				prixUnitaireHt: 100 + i,
				remiseLignePct: 0,
				tauxTva: i % 5 === 0 ? 10 : 20
			}
		});
		if (o.ouvrage !== false) {
			const issue = instancierOuvrage(plancherChauffantFictif(), {
				cle: "ouv1",
				ordre: 1e3,
				quantitePrincipale: 120,
				saisies: { bande: 44 },
				mode: o.mode ?? "eclate"
			});
			if (issue.etat !== "pret") throw new Error(issue.motif);
			elements.push({
				type: "ouvrage",
				ordre: 1e3,
				instance: issue.instance
			});
		}
		return elements;
	}

